								if (mem_rdata_latched[11:10] == 2'b10) begin // C.ANDI
									is_alu_reg_imm <= 1;
									decoded_rd <= 8 + mem_rdata_latched[9:7];

1177:	localparam cpu_state_shift  = 8'b00000100;
1193:		if (cpu_state == cpu_state_shift)  dbg_ascii_state = "shift";
1710:						cpu_state <= cpu_state_shift;
1742:									cpu_state <= cpu_state_shift;
1792:						cpu_state <= cpu_state_shift;
1829:			cpu_state_shift: begin
2131:			if (cpu_state == cpu_state_shift)  ok = 1;

